    },
    {
      "source": "aztec/final_permit.pdf",
      "locator": "Page 9, Section part_i, Condition/Criteria table, Test Acceptability Criteria (Ceriodaphnia dubia)",
      "exact_span": "≥80% survival of all control organisms. Average of 15 or more neonates per surviving control female. 60% of surviving control females must produce 3 broods.",
