    },
    {
      "source": "aztec/final_permit.pdf",
      "locator": "Page 9, Section part_i, Condition/Criteria table, Coefficient of Variation",
      "exact_span": "40% or less, unless significant effects are exhibited.",
      "affected_purpose": "A,B,C",
      "computation_change_reason": "The CV ceiling and its 'unless significant effects are exhibited' exception govern test precision and validity; interpreting when the exception applies could change whether endpoint data are admissible for limit comparisons (A), whether retesting or additional monitoring is required (B), and whether results are documented evidence or unresolved (C)."
    },
    {
